INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "highlights", "results", "in_hero", "hero_order") VALUES ('01M3ZCX9P93QJ1AMS8HMHVJRSB', 'presbyterian-academy', 'published', '2026-10-02T22:49:11.113Z', '2026-10-02T23:19:28.024Z', '2026-10-02T22:49:12.607Z', 8, 'en', '01M3ZCX9P93QJ1AMS8HMHVJRSB', 'The Presbyterian Academy', 'The Presbyterian Academy', 'school', 'Designer, Developer', 'A launch site for a brand-new Reformed lay formation school that needed to explain what it is, who it''s for, and how to enroll, all before the first cohort began.', '{"id":"01M3ZCX2FXJ1J7KBZ45364JT0M","provider":"local","filename":"presbyterian-academy.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LcOzJO~qs:D%RjR*ayxaW=MxWBxu","dominantColor":"rgb(204,201,193)","alt":"The The Presbyterian Academy homepage","meta":{"storageKey":"5P1BMZTRQV4SA72BZHBZ1XHMD9.png","caption":null,"blurhash":"LcOzJO~qs:D%RjR*ayxaW=MxWBxu","dominantColor":"rgb(204,201,193)"}}', 2026, 1, '2026-06-15T00:00:00.000Z', 'https://www.presbyterianacademy.org', 'A credible front door for a brand-new school: clear catalog, real faculty, honest pricing.', 'The hardest call on this one was pricing. Everybody told me to bury the numbers and make people call, but this audience is weighing a semester-long commitment, and they respect being given straight answers. Putting the tiers and the scholarship process out in the open drew the people who were actually ready to think about enrolling, which is worth far more than the leads you lose by showing the numbers early.', '[{"_key":"k41","_type":"block","children":[{"_key":"k40","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k43","_type":"block","children":[{"_key":"k42","_type":"span","marks":[],"text":"The Presbyterian Academy is a Reformed lay formation school launched in 2026 by the Presbytery of Cincinnati. The mission is adult theological education in cohort form: semester-length in-person courses for people who want to study Reformed theology seriously but are not pursuing ordination. There is nothing quite like it in the region."}],"markDefs":[],"style":"normal"},{"_key":"k45","_type":"block","children":[{"_key":"k44","_type":"span","marks":[],"text":"They came to us with the name, the faculty, and a start date. The site needed to do three things before the first enrollment cycle closed: explain what the Academy is, establish that it is serious, and convert interested visitors into enrolled students or at minimum a scheduled intro call."}],"markDefs":[],"style":"normal"},{"_key":"k47","_type":"block","children":[{"_key":"k46","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k49","_type":"block","children":[{"_key":"k48","_type":"span","marks":[],"text":"Brand-new organizations have a trust problem that established ones do not. There is no press coverage to cite, no multi-year alumni network to quote, and no decades of institutional history to point to. The site had to build credibility from what actually existed: a compelling faculty roster, specific course descriptions, and pricing that did not hedge."}],"markDefs":[],"style":"normal"},{"_key":"k4b","_type":"block","children":[{"_key":"k4a","_type":"span","marks":[],"text":"We organized the architecture around three conversion questions in sequence. What is this? Is it for me? How do I start? Every page answers at least one of those. The homepage handles the first. The course catalog and faculty directory handle the second. The enrollment and contact pages handle the third."}],"markDefs":[],"style":"normal"},{"_key":"k4d","_type":"block","children":[{"_key":"k4c","_type":"span","marks":[],"text":"For the visual language, we landed on what we called bookish minimalism: warm near-white paper tones, near-black ink, deep forest green anchoring the palette, and brass hairlines as structural dividers. Display type in Fraunces paired with Source Sans 3 for body. No hero photography of empty lecture halls; the design is text-forward because the product is text-forward."}],"markDefs":[],"style":"normal"},{"_key":"k4f","_type":"block","children":[{"_key":"k4e","_type":"span","marks":[],"text":"The CMS runs on Sanity so the Academy team can update courses, faculty, terms, and enrollment status from a dashboard without involving a developer."}],"markDefs":[],"style":"normal"},{"_key":"k4h","_type":"block","children":[{"_key":"k4g","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k4j","_type":"block","children":[{"_key":"k4i","_type":"span","marks":[],"text":"The full build, including the pieces above:"}],"markDefs":[],"style":"normal"},{"_key":"k4l","_type":"block","children":[{"_key":"k4k","_type":"span","marks":[],"text":"Course catalog with individual course pages, including a sticky enrollment-action aside on desktop so the sign-up path stays visible while visitors read the course description"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4n","_type":"block","children":[{"_key":"k4m","_type":"span","marks":[],"text":"Faculty directory with full biographical profiles, written to establish the weight of the teaching roster"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4p","_type":"block","children":[{"_key":"k4o","_type":"span","marks":[],"text":"Term listings showing enrollment periods with open/closed status and upcoming dates"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4r","_type":"block","children":[{"_key":"k4q","_type":"span","marks":[],"text":"Pricing tiers and need-based scholarship information, presented without \"contact us for pricing\" hedging, because the audience making a semester-long commitment deserves straight numbers"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4t","_type":"block","children":[{"_key":"k4s","_type":"span","marks":[],"text":"Testimonials section seeded from early cohort participants"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4v","_type":"block","children":[{"_key":"k4u","_type":"span","marks":[],"text":"Express interest form connected to Web3Forms for visitors who are ready to raise their hand"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4x","_type":"block","children":[{"_key":"k4w","_type":"span","marks":[],"text":"Calendly integration for intro call scheduling alongside the form"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k4z","_type":"block","children":[{"_key":"k4y","_type":"span","marks":[],"text":"Homepage with a six-image Ken Burns slideshow hero that sets an academic, bookish tone without requiring event photography"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k51","_type":"block","children":[{"_key":"k50","_type":"span","marks":[],"text":"Enrollment status live in the site header so every page shows whether the current term is open or closed"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k53","_type":"block","children":[{"_key":"k52","_type":"span","marks":[],"text":"Full Sanity CMS for courses, faculty, terms, testimonials, and configuration"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCX3SY8MT9DHJJB1HDK899","provider":"local","filename":"presbyterian-academy-home.png","mimeType":"image/png","width":1425,"height":5690,"blurhash":"LkNKCm%Mofof~qxuoeWB00t7afRj","dominantColor":"rgb(173,176,169)","alt":"The Presbyterian Academy homepage, scrolling top to bottom","meta":{"storageKey":"6VJW1CPXN36GRFKV8SSH7C7WDY.png","caption":null,"blurhash":"LkNKCm%Mofof~qxuoeWB00t7afRj","dominantColor":"rgb(173,176,169)"}}', '{"id":"01M3ZCX58Q6S7B9FMB6ZGE1T6Y","provider":"local","filename":"presbyterian-academy-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"L6Qvq8IU9F~p00-:-:tR00og%Mof","dominantColor":"rgb(221,220,215)","alt":"","meta":{"storageKey":"5CVH2VBJNT0WVQBMY402YGYGMR.png","caption":null,"blurhash":"L6Qvq8IU9F~p00-:-:tR00og%Mof","dominantColor":"rgb(221,220,215)"}}', 'The Presbyterian Academy homepage, scrolling top to bottom', 'https://www.presbyterianacademy.org', 'presbyterianacademy.org', 'scroll', '[{"alt":"The Presbyterian Academy course catalog","caption":"Every course shows its topic, teacher, term, and price at a glance, with an open or waitlist status, so a visitor can size up the fit without emailing to ask.","image":{"alt":"The Presbyterian Academy course catalog","blurhash":"LPRMYrIU-;.8_2xuWBoe~q-;D%Rj","dominantColor":"rgb(231,230,228)","filename":"presbyterian-academy-feature-catalog.png","height":900,"id":"01M3ZCX6D07AJ9C5CCJFZDHM4F","meta":{"blurhash":"LPRMYrIU-;.8_2xuWBoe~q-;D%Rj","caption":null,"dominantColor":"rgb(231,230,228)","storageKey":"2YVF445SYZ39E88JGXV34J867A.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"A catalog that answers ''is it for me?''"},{"alt":"The Presbyterian Academy faculty directory","caption":"A full profile for every teacher, each an ordained minister or credentialed scholar, does the trust-building a brand-new school cannot lean on history for.","image":{"alt":"The Presbyterian Academy faculty directory","blurhash":"LES6JRxuofxu~qt6t7xu-;t7Rj%M","dominantColor":"rgb(239,237,233)","filename":"presbyterian-academy-feature-faculty.png","height":900,"id":"01M3ZCX7F811AGFGG1M3NQSPWN","meta":{"blurhash":"LES6JRxuofxu~qt6t7xu-;t7Rj%M","caption":null,"dominantColor":"rgb(239,237,233)","storageKey":"14FXBA45R0VWHANQF41TWFYSBH.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"right","title":"Credibility from the people teaching"}]', '[{"text":"A brand-new school now has a credible front door, with a clear catalog, real faculty, and honest pricing, ready for its first enrollment cycle."},{"text":"An interested visitor can size up the fit, then take a clear next step through the express-interest form or an intro call."},{"text":"Full faculty profiles and a course catalog now do the credibility work a brand-new institution cannot lean on history for."},{"text":"The Academy team can update courses, faculty, terms, and enrollment status from a dashboard without involving a developer."},{"text":"Pricing tiers and the scholarship process are published up front, with no \"contact us for pricing\" hedging."}]', 1, 5);
INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "results") VALUES ('01M3ZCXHQNQCFMX8JK1J5W5851', 'reid-design', 'published', '2026-10-02T22:49:19.349Z', '2026-10-02T23:19:34.538Z', '2026-10-02T22:49:20.787Z', 8, 'en', '01M3ZCXHQNQCFMX8JK1J5W5851', 'Reid Design', 'Reid Design', 'small-business', 'Designer, Developer', 'A portfolio and booking site for an Indianapolis interior designer that turns browsers into qualified consultation requests before they ever pick up the phone.', '{"id":"01M3ZCXDCHRQT9FWS4F3Z8BHWG","provider":"local","filename":"reid-design.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LoFiDMt7fQj[~pj[ayj[?bofayj[","dominantColor":"rgb(113,110,106)","alt":"The Reid Design homepage","meta":{"storageKey":"1QBG5KEP3QXSGKBVNGDMJG791N.png","caption":null,"blurhash":"LoFiDMt7fQj[~pj[ayj[?bofayj[","dominantColor":"rgb(113,110,106)"}}', 2026, 1, '2026-05-15T00:00:00.000Z', 'https://www.reiddesignllc.com', 'Turns browsers into qualified consultation requests before they ever pick up the phone.', 'The detail I keep coming back to is the before/after slider. Finished rooms always photograph well, but until you can see the starting point, you cannot tell whether the change is something that could happen in your own house.', '[{"_key":"k55","_type":"block","children":[{"_key":"k54","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k57","_type":"block","children":[{"_key":"k56","_type":"span","marks":[],"text":"Staci Perkins runs Reid Design out of Plainfield, Indiana, serving homeowners across the Greater Indianapolis suburbs with everything from a single consultation hour to full-service room transformations. The work is genuinely strong. The existing digital presence was not."}],"markDefs":[],"style":"normal"},{"_key":"k59","_type":"block","children":[{"_key":"k58","_type":"span","marks":[],"text":"The brief had two parts. First, make the portfolio actually work as a sales tool, not just a gallery of nice rooms. Second, build something Staci can keep updated herself as new projects finish. Her ideal outcome was a site that does meaningful qualification work before a lead ever calls her."}],"markDefs":[],"style":"normal"},{"_key":"k5b","_type":"block","children":[{"_key":"k5a","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k5d","_type":"block","children":[{"_key":"k5c","_type":"span","marks":[],"text":"Interior design clients almost always have two blockers early in the process: they do not know what things cost, and they do not know whether their taste matches what the designer actually does. We built around both of those."}],"markDefs":[],"style":"normal"},{"_key":"k5f","_type":"block","children":[{"_key":"k5e","_type":"span","marks":[],"text":"The portfolio needed before/after pairs, not just finished rooms. Seeing the starting point is what makes the transformation land. The filter chips let visitors sort by room type and style so someone looking for a farmhouse kitchen can go straight to those projects instead of scrolling past twenty results that do not apply to them."}],"markDefs":[],"style":"normal"},{"_key":"k5h","_type":"block","children":[{"_key":"k5g","_type":"span","marks":[],"text":"For the pricing question, we built a Budget Calculator that lets visitors build their own scope estimate. It is not a quote; it is a self-qualification tool. Someone who walks through a full primary suite renovation and sees a range they can stomach is a much warmer lead than someone who calls cold with no idea what to expect. The Style Quiz serves a similar function on the creative side: it identifies a visitor''s design archetype and primes both the client and Staci for a more productive first call."}],"markDefs":[],"style":"normal"},{"_key":"k5j","_type":"block","children":[{"_key":"k5i","_type":"span","marks":[],"text":"We chose Astro and Sanity so Staci can add new projects, publish journal posts, and update press coverage without touching a line of code."}],"markDefs":[],"style":"normal"},{"_key":"k5l","_type":"block","children":[{"_key":"k5k","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k5n","_type":"block","children":[{"_key":"k5m","_type":"span","marks":[],"text":"Portfolio with before/after comparison sliders and Room x Style filter chips so visitors can find relevant work fast"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5p","_type":"block","children":[{"_key":"k5o","_type":"span","marks":[],"text":"Budget Calculator with room type, scope, and add-on selectors that outputs an estimated project range"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5r","_type":"block","children":[{"_key":"k5q","_type":"span","marks":[],"text":"Style Quiz that identifies a visitor''s design archetype and primes them for the consultation call"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5t","_type":"block","children":[{"_key":"k5s","_type":"span","marks":[],"text":"E-design service page for productized remote design, built with a toggleable coming-soon state while Staci prepares the offering"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5v","_type":"block","children":[{"_key":"k5u","_type":"span","marks":[],"text":"Lead magnet download hub with email capture for guides and planning resources"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5x","_type":"block","children":[{"_key":"k5w","_type":"span","marks":[],"text":"Affiliate shop (\"Shop My Favorites\") organized by room type with FTC disclosure built into the page design"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k5z","_type":"block","children":[{"_key":"k5y","_type":"span","marks":[],"text":"Journal with seven custom content block types covering project walkthroughs, product roundups, and process breakdowns"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k61","_type":"block","children":[{"_key":"k60","_type":"span","marks":[],"text":"Press coverage strip for earned media and magazine features"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k63","_type":"block","children":[{"_key":"k62","_type":"span","marks":[],"text":"Resources hub that ties the quiz, calculator, and guides together in one place so visitors can self-serve before reaching out"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k65","_type":"block","children":[{"_key":"k64","_type":"span","marks":[],"text":"Full Sanity CMS for portfolio projects, journal posts, press entries, and site-wide configuration"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCXEMV6HM8J9G1T9G39T67","provider":"local","filename":"reid-design-home.png","mimeType":"image/png","width":1425,"height":8553,"alt":"The Reid Design homepage, scrolling top to bottom","meta":{"storageKey":"7XE0BA144DPJ0D26A7YJEGT3N3.png","caption":null,"blurhash":null,"dominantColor":null}}', '{"id":"01M3ZCXFRBMBAGRY0NYWDCHNX6","provider":"local","filename":"reid-design-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"L9P6?W^Q%J~q00eAa^Rj00S~IqNG","dominantColor":"rgb(204,200,196)","alt":"","meta":{"storageKey":"1KE5KX7WTQCKFV5EJK42ZKEG95.png","caption":null,"blurhash":"L9P6?W^Q%J~q00eAa^Rj00S~IqNG","dominantColor":"rgb(204,200,196)"}}', 'The Reid Design homepage, scrolling top to bottom', 'https://www.reiddesignllc.com', 'reiddesignllc.com', 'scroll', '[{"text":"By the time someone books a consultation, the site has already walked them through scope and style, so the first call starts from shared understanding instead of square one."},{"text":"Before/after sliders turned the portfolio from an aspirational gallery into something persuasive, so visitors can see whether a transformation could happen in their own house."},{"text":"The Budget Calculator lets homeowners self-qualify on price by building their own scope estimate before they ever call."},{"text":"Staci can add new projects, publish journal posts, and update press coverage herself without touching a line of code."},{"text":"Filter chips let visitors sort by room type and style, so someone after a farmhouse kitchen goes straight to relevant work instead of scrolling past projects that do not apply."}]');
INSERT OR REPLACE INTO ec_case_studies ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "client", "sector", "role", "summary", "cover", "year", "featured", "published", "live_url", "outcome", "designer_note", "body", "showcase_desktop", "showcase_mobile", "showcase_alt", "showcase_href", "showcase_label", "showcase_variant", "highlights", "before_image", "before_alt", "before_label", "after_image", "after_alt", "after_label", "results", "in_hero", "hero_order") VALUES ('01M3ZCVAAJR0RXJ6TC4SYQF825', 'second-presbyterian-chicago', 'published', '2026-10-02T22:48:06.226Z', '2026-10-02T23:19:40.368Z', '2026-10-02T22:48:07.673Z', 10, 'en', '01M3ZCVAAJR0RXJ6TC4SYQF825', 'Second Presbyterian Church of Chicago', 'Second Presbyterian Church of Chicago', 'church', 'Designer, Developer', 'A full rebuild from Squarespace that organized a historic congregation''s deep programming behind a clear front door for first-time visitors.', '{"id":"01M3ZCPCKQKHGQKJW4XNYNKTB3","provider":"local","filename":"second-presbyterian-chicago.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)","alt":"The Second Presbyterian Church of Chicago homepage","meta":{"storageKey":"3YFB3122TA96GZZ57DZM67WXMZ.png","caption":null,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)"}}', 2026, 1, '2026-05-01T00:00:00.000Z', 'https://www.secondpreschicago.org', 'A historic congregation''s deep programming, finally organized behind a front door first-time visitors can actually use.', 'Second Pres has real depth: a serious music program and a food ministry that feeds the neighborhood every week. A congregation like that needed a site that gives its programming real estate, not one I flattened down to a tidy three-section homepage that would have shortchanged the people who actually use it every week. So I kept the front door simple for guests, with all that depth one click away.', '[{"_key":"k67","_type":"block","children":[{"_key":"k66","_type":"span","marks":[],"text":"The brief"}],"markDefs":[],"style":"h2"},{"_key":"k69","_type":"block","children":[{"_key":"k68","_type":"span","marks":[],"text":"Second Presbyterian Church of Chicago is a historic congregation in the city''s South Loop, worshiping in a National Historic Landmark known as the Church of the Angels for the painted angels across its Arts and Crafts ceiling and its nine Tiffany windows. The programming runs as deep as the building''s history, and Sunday morning draws a mix of longtime members, neighbors, and first-time visitors trying to figure out what they are walking into. The site they came in with was working, but only for people who already knew where to look. Service times were buried. The sermon archive was hard to search. Staff updates were slow because the previous platform made small edits feel like a project."}],"markDefs":[],"style":"normal"},{"_key":"k6b","_type":"block","children":[{"_key":"k6a","_type":"span","marks":[],"text":"Leadership wanted a full rebuild, not a refresh. The brief was specific: fast front door for guests, deep resource library for members, and a CMS the communications staff could actually use on a Tuesday."}],"markDefs":[],"style":"normal"},{"_key":"k6d","_type":"block","children":[{"_key":"k6c","_type":"span","marks":[],"text":"The approach"}],"markDefs":[],"style":"h2"},{"_key":"k6f","_type":"block","children":[{"_key":"k6e","_type":"span","marks":[],"text":"We started by mapping the two distinct audiences and where they were likely to land. First-time visitors needed a short path to service times, parking, and what to expect on a Sunday morning. Regular members needed to reach the sermon archive, upcoming events, and ministry sign-ups in one click. The challenge was that these two groups needed completely different experiences from the same homepage."}],"markDefs":[],"style":"normal"},{"_key":"k6h","_type":"block","children":[{"_key":"k6g","_type":"span","marks":[],"text":"The architecture we settled on gives visitors a clear \"Plan a Visit\" lane that answers the four questions most of them have before they decide to show up. Everything else sits one level deeper: sermon archive, community group listings, music ministry, food outreach, weddings, and venue rental. The depth is there; it just does not crowd the front door."}],"markDefs":[],"style":"normal"},{"_key":"k6j","_type":"block","children":[{"_key":"k6i","_type":"span","marks":[],"text":"For the CMS, we chose Sanity so the team could manage the sermon archive, event calendar, and staff directory without touching code. Sermons carry full liturgical metadata, including who served, which hymns were sung, the lectionary day, and links to bulletins and worship notes. That makes the archive useful for both personal spiritual reference and denominational records."}],"markDefs":[],"style":"normal"},{"_key":"k6l","_type":"block","children":[{"_key":"k6k","_type":"span","marks":[],"text":"What we built"}],"markDefs":[],"style":"h2"},{"_key":"k6n","_type":"block","children":[{"_key":"k6m","_type":"span","marks":[],"text":"The full build, including the pieces above:"}],"markDefs":[],"style":"normal"},{"_key":"k6p","_type":"block","children":[{"_key":"k6o","_type":"span","marks":[],"text":"Headless CMS (Sanity) for sermons, events, staff, and all content the team updates weekly"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6r","_type":"block","children":[{"_key":"k6q","_type":"span","marks":[],"text":"Single-sourced worship time that populates the site header, footer, visit page, and Google structured data from one field, so a service-time change requires exactly one edit"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6t","_type":"block","children":[{"_key":"k6s","_type":"span","marks":[],"text":"Sermon archive with liturgical metadata: officiant, choir, lectionary day, hymns, bulletins, and streaming links"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6v","_type":"block","children":[{"_key":"k6u","_type":"span","marks":[],"text":"Events calendar covering both recurring ministry schedules and one-time events with detail pages"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6x","_type":"block","children":[{"_key":"k6w","_type":"span","marks":[],"text":"Get Involved section organized around four tracks: Grow (community groups), Serve (outreach partners), Kids, and Food Ministry (the weekday Lunch Bag program and the Sunday South Loop Community Table)"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k6z","_type":"block","children":[{"_key":"k6y","_type":"span","marks":[],"text":"Weddings page with sanctuary history, a practical FAQ, and an inquiry workflow for couples booking the historic space"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k71","_type":"block","children":[{"_key":"k70","_type":"span","marks":[],"text":"Music page covering the quartette choir and the church''s historic Austin pipe organ in enough depth for visitors who care about sacred music"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k73","_type":"block","children":[{"_key":"k72","_type":"span","marks":[],"text":"Venue rental page for organizations wanting to use the building"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"},{"_key":"k75","_type":"block","children":[{"_key":"k74","_type":"span","marks":[],"text":"Give page connected to Vanco for online giving and designated gift categories"}],"level":1,"listItem":"bullet","markDefs":[],"style":"normal"}]', '{"id":"01M3ZCV1SY4FV3D5NNX2Q1CB0Z","provider":"local","filename":"second-presbyterian-chicago-home.png","mimeType":"image/png","width":1425,"height":5645,"blurhash":"LNLNrd_3azRj~W-;WBM{00ofayV[","dominantColor":"rgb(152,155,147)","alt":"The Second Presbyterian Church of Chicago homepage, scrolling top to bottom","meta":{"storageKey":"0QW5T0SMZJTW9GPTRZC9D7R4F0.png","caption":null,"blurhash":"LNLNrd_3azRj~W-;WBM{00ofayV[","dominantColor":"rgb(152,155,147)"}}', '{"id":"01M3ZCV3NGJJF2F909VXX6X04G","provider":"local","filename":"second-presbyterian-chicago-mobile.png","mimeType":"image/png","width":545,"height":4000,"blurhash":"LRLqIR%L%M%M4nj[xuj[~poft7of","dominantColor":"rgb(163,158,149)","alt":"","meta":{"storageKey":"2YP4HM87PQCTC36HSFHK13MSQA.png","caption":null,"blurhash":"LRLqIR%L%M%M4nj[xuj[~poft7of","dominantColor":"rgb(163,158,149)"}}', 'The Second Presbyterian Church of Chicago homepage, scrolling top to bottom', 'https://www.secondpreschicago.org', 'secondpreschicago.org', 'scroll', '[{"alt":"The Plan a Visit page on the new Second Presbyterian site","caption":"Service times, what to expect on a Sunday, and how to find the building, answered up front so a guest never has to dig for the basics.","image":{"alt":"The Plan a Visit page on the new Second Presbyterian site","blurhash":"LkI}kixtj[of4nWBWBj[~pofayfQ","dominantColor":"rgb(135,128,120)","filename":"second-presbyterian-chicago-feature-visit.png","height":900,"id":"01M3ZCV4XV5BBNXYFB05ZKYF55","meta":{"blurhash":"LkI}kixtj[of4nWBWBj[~pofayfQ","caption":null,"dominantColor":"rgb(135,128,120)","storageKey":"2BQ33AJC35T7PT9AC23TP210EX.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"A front door built for first-time guests"},{"alt":"The sermon archive on the new Second Presbyterian site","caption":"Every message carries its full liturgical metadata, officiant, scripture, hymns, and a streaming link, so it serves personal study and the denominational record alike.","image":{"alt":"The sermon archive on the new Second Presbyterian site","blurhash":"LIP6,AD*t7~p?HIUWBxuV?^+RjD%","dominantColor":"rgb(195,195,186)","filename":"second-presbyterian-chicago-feature-sermons.png","height":900,"id":"01M3ZCV62GJZC50ZDTF1DQD00P","meta":{"blurhash":"LIP6,AD*t7~p?HIUWBxuV?^+RjD%","caption":null,"dominantColor":"rgb(195,195,186)","storageKey":"3VKHPTJPFYS8K2V3YFY1GQ82VZ.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"right","title":"A sermon archive with real depth"},{"alt":"The Get Involved section with its four ministry tracks","caption":"The week''s ministries sit behind four plain doors, Grow, Serve, Kids, and Food, so members reach their next step in a click without crowding the guest path.","image":{"alt":"The Get Involved section with its four ministry tracks","blurhash":"LCRV%$^+s+?b~qafoJayD$t6xuoJ","dominantColor":"rgb(239,233,223)","filename":"second-presbyterian-chicago-feature-community.png","height":900,"id":"01M3ZCV75549AKFWFDVG3RPMWC","meta":{"blurhash":"LCRV%$^+s+?b~qafoJayD$t6xuoJ","caption":null,"dominantColor":"rgb(239,233,223)","storageKey":"0BQW67FMEZ8BCHFEGXE8C4NREA.png"},"mimeType":"image/png","provider":"local","width":1440},"side":"left","title":"Deep programming, clearly organized"}]', '{"id":"01M3ZCV86ZJ4ERG39NVYRZPEDW","provider":"local","filename":"second-presbyterian-chicago-before.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LMG8.fxuNHofE2D*tRtR~qt7aeRj","dominantColor":"rgb(127,119,112)","alt":"The previous Squarespace site for Second Presbyterian Church of Chicago","meta":{"storageKey":"5HTPX58J9BGHPHPYH9YMYFB8GM.png","caption":null,"blurhash":"LMG8.fxuNHofE2D*tRtR~qt7aeRj","dominantColor":"rgb(127,119,112)"}}', 'The previous Squarespace site for Second Presbyterian Church of Chicago', 'Before', '{"id":"01M3ZCPCKQKHGQKJW4XNYNKTB3","provider":"local","filename":"second-presbyterian-chicago.png","mimeType":"image/png","width":1440,"height":1080,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)","alt":"The redesigned Second Presbyterian Church of Chicago homepage","meta":{"storageKey":"3YFB3122TA96GZZ57DZM67WXMZ.png","caption":null,"blurhash":"LZNmi[~pjZD%WUV@ayt7s:IUWB%2","dominantColor":"rgb(187,182,173)"}}', 'The redesigned Second Presbyterian Church of Chicago homepage', 'After', '[{"text":"Anyone on the communications team can now add a sermon or update the staff directory in a few minutes, work that used to require a developer."},{"text":"First-time visitors get a clear front door to the church''s deep programming instead of a site that only worked for people who already knew where to look."},{"text":"A service-time change is now one edit that updates the header, footer, visit page, and Google''s structured data at once, instead of four separate edits that drift out of sync."},{"text":"Guests now have a short, clear path to service times, parking, and what to expect on a Sunday, the basics that used to be buried."}]', 1, 1);
INSERT OR REPLACE INTO ec_site_settings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "studio_name", "owner_name", "email", "phone", "location", "tagline", "instagram_url", "linkedin_url", "header_cta_label", "footer_currently", "cta_default_title", "cta_default_sub", "cta_default_label", "default_description", "rss_title", "rss_description") VALUES ('01M40WPJ88XAWHBTWMYRA25FBG', 'site', 'published', '2026-10-03T12:44:22.152Z', '2026-10-03T12:44:23.704Z', '2026-10-03T12:44:23.704Z', 2, 'en', '01M40WPJ88XAWHBTWMYRA25FBG', 'Nixon Creative Studio', 'Nathan Nixon', 'nathan@nixoncreativestudio.com', '(256) 318-6627', 'Cincinnati, OH', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.', 'https://www.instagram.com/thenate_n/', 'https://www.linkedin.com/in/nathannixon/', 'Start a project', 'Booking small business and nonprofit web projects for the season ahead, with a few photography days mixed in.', 'Let''s build a site you won''t have to redo.', 'I take a small number of projects each quarter. The earlier we talk, the better we can pace it together.', 'Start a project', 'Nixon Creative Studio', 'Nixon Creative Studio — Case Studies', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.');
INSERT OR REPLACE INTO ec_page_home ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "hero_heading", "hero_heading_accent", "hero_positioning", "hero_proof_before", "hero_proof_link_text", "hero_proof_after", "hero_primary_label", "hero_secondary_label", "work_heading", "work_sub", "work_link_label", "pricing_heading", "pricing_sub", "pricing_includes_lead", "pricing_includes", "pricing_reassurance", "pricing_link_label", "process_heading", "process_sub", "process_steps", "process_cta_title", "process_cta_sub", "process_cta_label") VALUES ('01M40ZCM6TR2WHV35YHM2XVQ7V', 'home', 'published', '2026-10-03T13:31:22.202Z', '2026-10-03T13:56:02.675Z', '2026-10-03T13:31:23.935Z', 11, 'en', '01M40ZCM6TR2WHV35YHM2XVQ7V', 'Nixon Creative Studio | Strategy-led design and photography', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.', 'I make websites that', 'pull their weight.', 'For churches, schools, nonprofits, and small businesses, wherever you are.', 'Based in Cincinnati. Every site designed, built, and photographed by', 'one person', ', start to finish.', 'Start a project', 'See the work', 'Selected work', 'A few recent projects. Each one started with a conversation about what the organization actually needed, not which template to pick.', 'Explore more projects', 'What it costs', 'Honest from the first conversation, so you can size up the fit before we ever talk.', 'Every build includes, whatever the tier:', '[{"text":"A custom design, yours to keep"},{"text":"100 / 100 accessibility"},{"text":"Strategy and a content system, included"},{"text":"One person, start to finish"}]', 'Every number is a starting point. The first conversation is free and ends with an honest ballpark, and larger projects can split into monthly payments.', 'See full pricing and services', 'How we work', 'Four steps, from the first conversation to launch day.', '[{"title":"Conversation","body":"We meet for an hour, in person or on video, and talk about what you actually need. No pitch deck, no agency theater. Just a working session that ends with a one-page brief we both agree on."},{"title":"Strategy","body":"I write the audience map, the page architecture, and the conversion path. You read it, push back, we revise. The strategy doc is the source of truth for every design choice that follows."},{"title":"Design and build","body":"Components, content, and pages built in the open. Preview links land in your inbox at every milestone so you can react early instead of seeing the whole thing for the first time at launch."},{"title":"Launch and follow-through","body":"We go live together, then I stay close for the first month to fix anything that surfaces. After that you own the site outright, with documentation and a simple way to reach me when something comes up."}]', 'Tell me what you are building.', 'I take a small number of projects each quarter. The earlier we talk, the better we can pace it together.', 'Start a project');
INSERT OR REPLACE INTO ec_page_services ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "heading", "intro", "pricing_heading", "pricing_sub", "pricing_footnote", "addons_heading", "why_heading", "why_sub", "why_items", "why_closing", "faq_heading", "faq_sub", "faq") VALUES ('01M40ZEWWZP2RJDW8MGAHK8280', 'services', 'published', '2026-10-03T13:32:36.639Z', '2026-10-03T13:32:37.940Z', '2026-10-03T13:32:37.940Z', 2, 'en', '01M40ZEWWZP2RJDW8MGAHK8280', 'Services', 'Strategy, web design, and brand work for clients anywhere, plus photography across the greater Cincinnati region. Based in Cincinnati.', 'Ready to scope a project?', 'The first conversation is free and lands at an honest ballpark by the end. Email is fastest, but a phone call works too.', 'Strategy, web design, and photography for organizations that care about the long run.', 'Most projects use all three services, in that order. Some use one or two. The first conversation always ends with an honest scope, not a sales pitch.', 'What a website costs', 'A starting point, not a fixed menu. Every build is custom and comes with a content system you can run yourself, so the tiers differ in scope and how much functionality you need, not whether the work is custom. The free first conversation ends with an honest ballpark, and larger projects can be split into monthly payments.', 'Strategy is the front of every project, not a line item. The price above already includes the session and the brief.', 'Add to any project', 'Why it costs what it costs', 'Plenty of people will quote you less. Here is what the price actually buys, and what a cheaper one usually leaves out.', '[{"title":"One person, no handoffs","body":"The person who plans your site designs it, builds it, and shoots the photos. No agency markup, and nothing lost in translation between a strategist, a designer, and a developer who never quite talk to each other."},{"title":"Built to be handed off","body":"Every site is set up so the next volunteer or staff member can keep it running, and you own it outright. A cheaper site that leaves you stranded the day the freelancer goes quiet costs far more to replace than it saved."},{"title":"Accessible by default","body":"Every page meets WCAG AA and scores 100 for accessibility. Most budget builds fail this badly. For a church, school, or nonprofit it is both the right thing to do and real legal cover, included, not an upsell."},{"title":"Cheap is expensive later","body":"A bargain site quietly runs into thousands a year once you bolt on the features it could not handle up front. I would rather build it once, on a stack that is nearly free to run and is yours to keep."}]', 'I build with modern tools, including AI-assisted workflows, the same way I use frameworks and a camera. They help one person do the work of a team. The strategy, the design, and the accountability stay mine, start to finish.', 'Common questions', 'The things people ask before the first call.', '[{"question":"What does it cost?","answer":"Websites start at $4,000 for a focused Launch site. Most projects land between $7,000 and $11,000, and builds with real custom functionality start around $12,000. Every build is custom and comes with a content system you can manage yourself; what moves the number is scope, functionality, photography, and content. The first conversation is free and ends with an honest ballpark before either of us is committed, and larger projects can be split into monthly payments so the budget is about cash flow, not one big wall."},{"question":"What if I have been quoted less somewhere else?","answer":"You probably can find a cheaper quote, and for a very simple need that might be the right call. What a low quote usually leaves out is the part that matters later: accessibility, a content system your team can actually run, a plan for who maintains the site after launch, and someone who still answers the phone in a year. A site you have to rebuild in eighteen months is the expensive one. I would rather build it once."},{"question":"How long does a typical project take?","answer":"Most websites land between six and ten weeks from kickoff to launch. Larger projects with custom photography or multiple content collections can run twelve to sixteen weeks. The brief at the end of strategy sets the real timeline."},{"question":"Do you offer maintenance?","answer":"Optional. After launch you own the site outright and can leave it alone for years if nothing breaks. If you want hands-on support, care plans start at $100 a month for updates, backups, and security, with higher tiers that add a monthly bucket of content edits."},{"question":"Can you work with my existing brand?","answer":"Yes. If you already have a logo, palette, and type system, we use it. If you do not, brand work can be folded into the strategy phase or scoped separately."},{"question":"Where are you based, and do you work with clients outside Cincinnati?","answer":"I''m based in Cincinnati, but web design, strategy, and brand work happen with clients anywhere, fully remote when that is easier. Photography is the one piece that needs me on site, so that stays within the greater Cincinnati region."}]');
INSERT OR REPLACE INTO ec_page_about ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "heading", "heading_accent", "intro", "headshot", "headshot_alt", "thesis_before", "thesis_accent", "thesis_after", "story_heading", "story_sub", "story_body", "outside_heading", "outside_sub", "photos", "principles_heading", "principles_sub", "principles", "currently_heading", "currently_sub", "currently_updated", "working_on", "booking", "reading", "learning", "testimonials_heading", "testimonials_sub", "lighthouse_performance", "lighthouse_accessibility", "lighthouse_best_practices", "lighthouse_seo", "job_title") VALUES ('01M40YHS7GDAJHYEFVWB53BRPT', 'about', 'published', '2026-10-03T13:16:42.608Z', '2026-10-03T13:16:44.657Z', '2026-10-03T13:16:44.657Z', 2, 'en', '01M40YHS7GDAJHYEFVWB53BRPT', 'About', 'About Nathan Nixon, sole owner of Nixon Creative Studio in Cincinnati, Ohio.', 'Want to talk about a project?', 'I take on a small number of projects each quarter. The earlier we talk, the easier it is to schedule the work.', 'A one-person studio for', 'organizations that take their work seriously.', 'I''m Nathan Nixon. I run Nixon Creative Studio out of Cincinnati, Ohio, and I work with small businesses, nonprofits, churches, and schools, in person around the region and anywhere for web work. I do the strategy, the design, the photography, and the code, so the person you meet on day one is the same person who hands you the finished site.', '{"id":"01M40XN6CQBCDG5ZTWGB2WK8E1","provider":"local","width":1200,"height":1200,"alt":"Nathan Nixon, smiling outdoors","meta":{"storageKey":"01M40XN5WPNDGF9W4T2VDH6K5J.jpg","caption":null,"blurhash":"L9D]Ct^$00EJW}j]~7kA0h9a}[xb","dominantColor":"rgb(89,93,60)"},"blurhash":"L9D]Ct^$00EJW}j]~7kA0h9a}[xb","dominantColor":"rgb(89,93,60)","filename":"headshot.jpg","mimeType":"image/jpeg"}', 'Nathan Nixon, smiling outdoors', 'One person on every project, start to finish: strategy, design, photography, and code. I work with', 'churches, schools, nonprofits, and small businesses', 'around Cincinnati in person, and anywhere for web work.', 'The longer story', 'From behind the camera to the web, and why one person handles all of it.', '[{"_type":"block","_key":"k1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"I came to this work through a camera. For years I photographed portraits, families, weddings, the events people most want to remember, and the part I loved was helping someone show up at their best. When the shoots dried up in 2020, I started building websites for a few of those same clients, and it turned out to be the same job in a new medium: work out what someone is really trying to say, then make it clear. Web design is the studio''s main work now, but the photographer''s eye stayed, and most projects still end up with real photography in them.","marks":[]}]},{"_type":"block","_key":"k3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2","text":"Before any of that I studied mechanical engineering at the University of Edinburgh, back home in Scotland. The degree did not make me a designer, but it taught me to take a thing apart, understand why each piece is there, and put it back together so it holds. That is how I approach a website too: structure first, surface second, and built so the person who inherits it can actually keep it running.","marks":[]}]},{"_type":"block","_key":"k5","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k4","text":"I also do plenty of this work as a volunteer. I''m on the media team at Crestview Presbyterian Church, where I run the weekly livestream, plan and buy the equipment upgrades, and shoot the photo and video the church uses for its website and its socials.","marks":[]}]},{"_type":"block","_key":"k7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k6","text":"Personally, I moved from Scotland to Cincinnati in 2017 to be with my wife, became a US citizen in 2022, and these days we''re raising two kids and buying our first house here. When I''m away from a screen I''m usually out on a long run, chasing landscapes with a camera, deep in an ambitious Lego build with the kids, or a few episodes into a history drama.","marks":[]}]}]', 'Outside the studio', 'A few snapshots from the rest of life around Cincinnati: family, the trails, and the occasional turn in front of the camera.', '[{"image":{"id":"01M40XN7WSAR1VY6MA1ZQ4D7WV","provider":"local","width":720,"height":1080,"alt":"Nathan with his family on a picnic blanket in a park, a young child eating watermelon.","meta":{"storageKey":"01M40XN7CW59FX16JKNFCC5AGW.jpg","caption":null,"blurhash":"LPJ[9TxaE%x=4TM_RkM_?^R%sDNK","dominantColor":"rgb(155,152,122)"},"blurhash":"LPJ[9TxaE%x=4TM_RkM_?^R%sDNK","dominantColor":"rgb(155,152,122)","filename":"family.jpg","mimeType":"image/jpeg"},"caption":"A park afternoon","alt":"Nathan with his family on a picnic blanket in a park, a young child eating watermelon."},{"image":{"id":"01M40XN9FR534CCRSYGNT5RGEW","provider":"local","width":1205,"height":1600,"alt":"Nathan and a friend at the end of a charity 5K, race bibs on, in a sunny parking lot.","meta":{"storageKey":"01M40XN8V08B20Y363GEQFW38V.jpg","caption":null,"blurhash":"L*DmzVWCV?of%%azj[bHo~jsoha}","dominantColor":"rgb(104,119,137)"},"blurhash":"L*DmzVWCV?of%%azj[bHo~jsoha}","dominantColor":"rgb(104,119,137)","filename":"running.jpg","mimeType":"image/jpeg"},"caption":"Race day","alt":"Nathan and a friend at the end of a charity 5K, race bibs on, in a sunny parking lot."},{"image":{"id":"01M40XNAZHXHD8MGE56HRC810X","provider":"local","width":1200,"height":1600,"alt":"Nathan carrying a small child on a sunny day in front of old railroad cars.","meta":{"storageKey":"01M40XNAF81YSV2QJQ8Q67SS12.jpg","caption":null,"blurhash":"LEF~5H~nys.99DxwixM{C8tmtTs=","dominantColor":"rgb(106,100,87)"},"blurhash":"LEF~5H~nys.99DxwixM{C8tmtTs=","dominantColor":"rgb(106,100,87)","filename":"exploring.jpg","mimeType":"image/jpeg"},"caption":"Out exploring","alt":"Nathan carrying a small child on a sunny day in front of old railroad cars."},{"image":{"id":"01M40XNCDC452Q40D536TRHKQ6","provider":"local","width":1079,"height":720,"alt":"Nathan and his wife laughing together on their wedding day, beside a lake.","meta":{"storageKey":"01M40XNBZ8P5FQVB9CBZVXK58Q.jpg","caption":null,"blurhash":"LZJHp.%NJ7^+_N%Lxug3tSMxs:of","dominantColor":"rgb(143,136,127)"},"blurhash":"LZJHp.%NJ7^+_N%Lxug3tSMxs:of","dominantColor":"rgb(143,136,127)","filename":"wedding.jpg","mimeType":"image/jpeg"},"caption":"Wedding day","alt":"Nathan and his wife laughing together on their wedding day, beside a lake."},{"image":{"id":"01M40XNDQRTN9TFW843MVASP10","provider":"local","width":1600,"height":1280,"alt":"A black-and-white studio portrait of Nathan looking off to the side.","meta":{"storageKey":"01M40XND6AAKNJQGECYX4GFJKX.jpg","caption":null,"blurhash":"L6BzC3-;000000IU%M~qae-;-;D%","dominantColor":"rgb(59,61,61)"},"blurhash":"L6BzC3-;000000IU%M~qae-;-;D%","dominantColor":"rgb(59,61,61)","filename":"portrait-bw.jpg","mimeType":"image/jpeg"},"caption":"From the other side of the lens","alt":"A black-and-white studio portrait of Nathan looking off to the side."}]', 'How I work', 'Three principles that hold across every project, big or small.', '[{"title":"Strategy before pixels","body":"Every project starts with a working session and a one-page brief we both agree on. Design choices follow from there, not from whichever template looks freshest."},{"title":"The right platform for the job","body":"Some clients are best served by a custom-coded site, others by Squarespace or WordPress. I pick what fits your budget and the people who will maintain it, then set it up so the next volunteer or staff member can keep it running after I hand it over."},{"title":"Cincinnati base, clients anywhere","body":"Based in Cincinnati, so local clients meet in person and get on-site photography. Web design and strategy go wherever the client is, fully remote when that is easier. Short distance when it helps, no distance when it does not."}]', 'Currently', 'A present-tense snapshot of the studio: current work, what I''m reading, and what I''m trying to get sharper on. Rewritten every couple of months.', '2026-10-01T00:00:00.000Z', '[{"text":"Finishing the Presbyterian Academy website ahead of the school''s first term."},{"text":"Buying our first house, here in Cincinnati."}]', '[{"label":"Web design","status":"open","detail":"Open to new web design projects of every kind this quarter, from a single landing page to a full rebuild."},{"label":"Photography","status":"limited","detail":"A few shoot days each month, fit around the web work, for portraits, families, events, and the brand photography that pairs with a new site."}]', '[{"title":"John Adams","author":"David McCullough"},{"title":"The New Father","author":"Armin A. Brott"},{"title":"The Lord of the Rings","author":"J.R.R. Tolkien","note":"re-reading"}]', '[{"text":"Smoother, steadier video out of my gimbal"},{"text":"Coaxing a genuinely lush green lawn out of the backyard"},{"text":"Going deeper on Astro, the framework this very site runs on"}]', 'What clients say', 'Real words from the churches, schools, and businesses I''ve built for.', 92, 100, 100, 100, 'Founder, Designer, Developer, Photographer');
INSERT OR REPLACE INTO ec_page_contact ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "cta_label", "heading", "heading_accent", "intro", "budgets", "timelines", "heard_from", "next_steps", "where_text") VALUES ('01M40ZBWYCBSN9N1D5PS1CP8RG', 'contact', 'published', '2026-10-03T13:30:58.380Z', '2026-10-03T13:31:00.419Z', '2026-10-03T13:31:00.419Z', 2, 'en', '01M40ZBWYCBSN9N1D5PS1CP8RG', 'Contact', 'Get in touch about a web design, brand, or photography project.', 'Rather skip the form?', 'Email or call me directly. A sentence about your project is enough to get started.', 'Email me', 'Start a project, or just', 'say hello.', 'The form sends straight to my inbox. If you''d rather email or call, those work just as well.', '[{"label":"Under $4,000"},{"label":"$4,000 to $7,000"},{"label":"$7,000 to $12,000"},{"label":"$12,000 or more"},{"label":"Not sure yet"}]', '[{"label":"Right away"},{"label":"In the next 1 to 3 months"},{"label":"3 to 6 months from now"},{"label":"More than 6 months out"},{"label":"Flexible, no fixed deadline"}]', '[{"label":"A referral from someone I know"},{"label":"Google or another search engine"},{"label":"Instagram, LinkedIn, or other social"},{"label":"I''ve worked with Nathan before"},{"label":"In person, at an event or through a church or school"},{"label":"Somewhere else"}]', '[{"text":"You send the form."},{"text":"I read it myself and reply within one or two business days."},{"text":"If we''re a fit, a half-hour call to talk it through."}]', 'In-person work and photography across the greater Cincinnati region; web design and strategy with clients anywhere, fully remote when that is easier.');
INSERT OR REPLACE INTO ec_page_work ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "eyebrow", "heading", "intro", "empty_filter_message", "live_heading", "live_body") VALUES ('01M40ZFD4XT2MV5K4MAC8FEYTB', 'work', 'published', '2026-10-03T13:32:53.277Z', '2026-10-03T13:32:54.726Z', '2026-10-03T13:32:54.726Z', 2, 'en', '01M40ZFD4XT2MV5K4MAC8FEYTB', 'Selected work', 'A list of recent web design, brand, and photography projects from Nixon Creative Studio.', 'Portfolio', 'Selected work', 'for churches, schools, nonprofits, and small businesses around Cincinnati. Each one started with a conversation about what the organization actually needed.', 'Nothing matches that filter yet. Try clearing one of the chips above.', 'Open any of them', 'Every project here is a real, shipped site. Do not take my word for it, click through and look around.');
INSERT OR REPLACE INTO ec_page_photography ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "cta_title", "cta_sub", "heading", "heading_accent", "intro", "events_title", "events_intro", "portraits_title", "portraits_intro", "environments_title", "environments_intro", "empty_heading", "empty_body") VALUES ('01M40ZEA8F9CSA05MH1MTZBGF8', 'photography', 'published', '2026-10-03T13:32:17.551Z', '2026-10-03T13:32:18.707Z', '2026-10-03T13:32:18.707Z', 2, 'en', '01M40ZEA8F9CSA05MH1MTZBGF8', 'Photography', 'Photography for churches, schools, nonprofits and small businesses around Cincinnati: events, portraits and spaces, from $900 for a half day.', 'Need photography for your project?', 'Day-of coverage, headshots, environments. Often paired with web work, sometimes booked on its own.', 'Photography that matches the', 'website it lives on.', 'Events, portraits, and spaces for organizations around Cincinnati, often shot for the website I am building at the same time, so the photos and the site look like one piece of work.', 'Events', 'Sunday mornings, school assemblies, fundraisers, ribbon cuttings. Coverage that tells the story without making the room perform for the camera.', 'Portraits', 'Team headshots, staff portraits, leadership pages. Comfortable lighting, consistent treatment, edited for web so the file size stays sane.', 'Environments', 'Lobbies, classrooms, sanctuaries, storefronts. The spaces visitors actually walk into, photographed in the light they actually see.', 'A public gallery is on its way.', 'I am gathering the best frames from recent church, school and small-business shoots, with each client''s permission. Until then, ask and I will send samples that fit your project.');
INSERT OR REPLACE INTO ec_page_journal ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "heading", "intro", "empty_kicker", "empty_heading", "empty_body") VALUES ('01M40ZDA40YFXAS52J3T8D5S55', 'journal', 'published', '2026-10-03T13:31:44.640Z', '2026-10-03T13:31:45.914Z', '2026-10-03T13:31:45.914Z', 2, 'en', '01M40ZDA40YFXAS52J3T8D5S55', 'Journal', 'Short essays, process notes, and field reports from the studio.', 'Journal', 'Notes from the studio: how a build goes, what I learn on a shoot, and the occasional opinion. I write one when there is something worth saying.', 'Nothing published yet.', 'The first entry is still in the drafts.', 'The case studies are the best account of how I work for now, and I am glad to talk a project through over email.');
INSERT OR REPLACE INTO ec_page_not_found ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "label", "heading", "body", "links") VALUES ('01M40ZDQYXC2PPF21YACK44Z02', 'not-found', 'published', '2026-10-03T13:31:58.813Z', '2026-10-03T13:31:59.980Z', '2026-10-03T13:31:59.980Z', 2, 'en', '01M40ZDQYXC2PPF21YACK44Z02', 'Page not found', 'That page wandered off. Here''s how to get back on track.', 'Page not found', 'That page wandered off.', 'The link you followed might be old, or the address might be a typo. Nothing''s broken on this end. Here are a few places to try instead.', '[{"label":"Back to home","href":"/"},{"label":"See selected work","href":"/work/"},{"label":"Get in touch","href":"/contact"}]');
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01M40WRHWJW9YDNWB4PQN4M3AB', 'flagship', 'published', '2026-10-03T12:45:27.314Z', '2026-10-03T12:45:28.568Z', '2026-10-03T12:45:28.568Z', 2, 'en', '01M40WRHWJW9YDNWB4PQN4M3AB', 'Flagship', 12000, '+', 'Advanced builds', 'Typically $12,000 and up', 'For organizations that need the site to do real work: custom interactive tools, advanced integrations, or a headless build for a large, complex site. The kind of build an agency would charge far more for.', '[{"text":"Custom interactive tools and features"},{"text":"Advanced and third-party integrations"},{"text":"A headless build for a large, deep site"}]', 0, 3);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "sort_order") VALUES ('01M40WR91E82HYHH7NHRCA3DAQ', 'launch', 'published', '2026-10-03T12:45:18.254Z', '2026-10-03T12:45:19.577Z', '2026-10-03T12:45:19.577Z', 2, 'en', '01M40WR91E82HYHH7NHRCA3DAQ', 'Launch', 4000, '+', 'Smaller organizations', 'Most land between $4,000 and $6,500', 'A focused custom site for a smaller organization: the essential pages done well, with content you can keep current yourself. The right fit when you want a clear, strong presence without a lot of moving parts.', '[{"text":"A focused set of core pages, designed around your goals"},{"text":"Content you can keep current yourself"},{"text":"Accessible and fast, set up and handed off"}]', 0, 1);
INSERT OR REPLACE INTO ec_pricing_tiers ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price_from", "price_suffix", "who", "range", "note", "features", "highlighted", "badge", "sort_order") VALUES ('01M40WRDC8TFC6JZMSNYQZG0TS', 'signature', 'published', '2026-10-03T12:45:22.696Z', '2026-10-03T12:45:23.758Z', '2026-10-03T12:45:23.758Z', 2, 'en', '01M40WRDC8TFC6JZMSNYQZG0TS', 'Signature', 7000, '+', 'Most projects', 'Most land between $7,000 and $11,000', 'The right fit for most projects: a larger custom site with deeper content, several content types your team manages itself, and the integrations a growing church, school, or business needs.', '[{"text":"A larger site with deeper content sections"},{"text":"Several content types your team manages itself"},{"text":"Integrations and search-engine work built in"}]', 1, 'Where most projects land', 2);
INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01M40WQKE1TD0W5KBRJD42H5HH', 'brand-strategy', 'published', '2026-10-03T12:44:56.129Z', '2026-10-03T12:44:57.293Z', '2026-10-03T12:44:57.293Z', 2, 'en', '01M40WQKE1TD0W5KBRJD42H5HH', 'Brand & strategy', '$500 to $2,000', 'Standalone strategy or brand-identity work for when you need it on its own. Strategy is already built into every website project.', 2);
INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01M40WQQT9MV1YWAFD7EQG6597', 'care-plan', 'published', '2026-10-03T12:45:00.617Z', '2026-10-03T12:45:01.946Z', '2026-10-03T12:45:01.946Z', 2, 'en', '01M40WQQT9MV1YWAFD7EQG6597', 'Care plan', 'from $100/mo', 'Optional. Updates, backups, security, and, on the higher tiers, a monthly bucket of small content edits. It does not cover major revisions or new features, which are quoted separately. Skip it and the site is still yours to leave alone for years, with no lock-in.', 3);
INSERT OR REPLACE INTO ec_pricing_addons ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "name", "price", "note", "sort_order") VALUES ('01M40WQFAAXGAARSKQ31F36ADV', 'photography', 'published', '2026-10-03T12:44:51.914Z', '2026-10-03T12:44:52.966Z', '2026-10-03T12:44:52.966Z', 2, 'en', '01M40WQFAAXGAARSKQ31F36ADV', 'Photography', 'from $900', 'Headshots, brand, and environmental photos shot for your site by the person who designed it. A half-day starts at $900 and a full day runs about $1,200, often folded into a build or booked on its own across the Cincinnati region.', 1);
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "price_from", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01M40ZG5Q3VSNP681TE2XVF8KB', 'photography', 'published', '2026-10-03T13:33:18.435Z', '2026-10-03T13:33:20.424Z', '2026-10-03T13:33:20.424Z', 2, 'en', '01M40ZG5Q3VSNP681TE2XVF8KB', 'Photography', 'Headshots, event coverage, and environmental photography shot for your website by the same person who designed it.', 'When the photographer and the designer are one person, the photos match the layout instead of fighting it. Images arrive edited, web-optimized, and ready to drop in.', 900, 'photography', '[{"text":"On-site Sunday or weekday coverage"},{"text":"Headshots for team and staff"},{"text":"Environmental photography of your space"},{"text":"Edited, web-optimized images delivered with the website"}]', 'regional', 3);
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "price_from", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01M40ZFXXH3ATG1QS32R3VNCP1', 'strategy', 'published', '2026-10-03T13:33:10.449Z', '2026-10-03T13:33:11.757Z', '2026-10-03T13:33:11.757Z', 2, 'en', '01M40ZFXXH3ATG1QS32R3VNCP1', 'Strategy', 'The planning work that decides what the site is for, who it serves, and how it earns its keep.', 'Strategy always comes first. Without it, design becomes decoration. We start with a working session, then I write a short brief that the rest of the project follows.', 1500, 'strategy', '[{"text":"A working session, then back-and-forth until the plan is right"},{"text":"Audience map and conversion path"},{"text":"Content inventory of what you already have"},{"text":"A one-page brief the rest of the project follows"}]', 'anywhere', 1);
INSERT OR REPLACE INTO ec_service_offerings ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "lede", "body", "image_alt", "placeholder_icon", "points", "area_served", "sort_order") VALUES ('01M40ZG1Y4P56JVKJTTWHRQ4HY', 'web-design', 'published', '2026-10-03T13:33:14.564Z', '2026-10-03T13:33:15.801Z', '2026-10-03T13:33:15.801Z', 2, 'en', '01M40ZG1Y4P56JVKJTTWHRQ4HY', 'Web design', 'Modern, accessible, fast websites built on the platform that fits you, from a custom-coded site to Squarespace or WordPress, and set up so your team can actually run it.', 'I match the build to your budget and to whoever will maintain it after launch. Everything is built mobile-first and tested for accessibility from the very first screen, then handed off so you are never locked out of your own site.', 'The Second Presbyterian Church of Chicago website, designed and built by the studio', 'none', '[{"text":"A custom design built to your brand, not a stock template"},{"text":"Self-hosted typography and imagery"},{"text":"Mobile-first responsive layouts"},{"text":"WCAG-aware accessibility from day one"},{"text":"Deployed to Cloudflare Pages, auto-rebuild on every commit"}]', 'anywhere', 2);
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "eyebrow", "summary", "intro", "content", "show_toc", "last_updated") VALUES ('01M40ZGW9YE8KXA5WKWSMBY6TW', 'accessibility', 'published', '2026-10-03T13:33:41.566Z', '2026-10-03T13:33:42.717Z', '2026-10-03T13:33:42.717Z', 2, 'en', '01M40ZGW9YE8KXA5WKWSMBY6TW', 'Accessibility', 'Built to be used by everyone.', 'Accessibility', 'How this site is built for keyboard and screen-reader users, how it''s tested, and how to report a problem.', '[{"_type":"block","_key":"k4","style":"normal","markDefs":[{"_key":"k1","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k0","text":"I build this site toward WCAG 2.1 AA and I check it on every change. No website is ever perfectly accessible, so if anything is hard to use with a keyboard or a screen reader, tell me and I''ll fix it: ","marks":[]},{"_type":"span","_key":"k2","text":"nathan@nixoncreativestudio.com","marks":["k1"]},{"_type":"span","_key":"k3","text":".","marks":[]}]}]', '[{"_type":"block","_key":"k1","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"The standard","marks":[]}]},{"_type":"block","_key":"k3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2","text":"The goal is WCAG 2.1 AA, the same standard most public bodies and larger organizations are held to, and it applies to every page. Each page is built to score 100 on Lighthouse''s accessibility audit, and an automated check runs on every change so that score does not quietly slip. That automated score is a useful floor, not a certificate: it catches the machine-checkable issues, which are only one part of the picture.","marks":[]}]},{"_type":"block","_key":"k5","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k4","text":"In practice","marks":[]}]},{"_type":"block","_key":"k7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k6","text":"A few of the things that means on this site:","marks":[]}]},{"_type":"block","_key":"k9","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k8","text":"Everything you can do with a mouse, you can do with a keyboard. The focus outline is always visible, and a \"Skip to main content\" link is the first thing you reach.","marks":[]}]},{"_type":"block","_key":"kb","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ka","text":"Real landmarks and a clean heading order, so a screen reader can move through a page by region and by heading instead of reading it all top to bottom.","marks":[]}]},{"_type":"block","_key":"kd","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kc","text":"Every form field has a visible label, uses the right input type, and announces its own errors rather than signalling them with color alone.","marks":[]}]},{"_type":"block","_key":"kf","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"ke","text":"Text is chosen to clear the AA contrast bar against every background it sits on, including the textured ones. Images that carry meaning have descriptions; purely decorative ones are hidden from assistive tech.","marks":[]}]},{"_type":"block","_key":"kh","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"kg","text":"If your device is set to reduce motion, the animations and the smooth scrolling switch off automatically.","marks":[]}]},{"_type":"block","_key":"kj","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ki","text":"How it is checked","marks":[]}]},{"_type":"block","_key":"ko","style":"normal","markDefs":[{"_key":"kl","_type":"link","href":"https://github.com/dequelabs/axe-core"}],"children":[{"_type":"span","_key":"kk","text":"The accessibility score is a hard gate: a change cannot ship if it drops a page below 100. On top of that, the pages are run through ","marks":[]},{"_type":"span","_key":"km","text":"axe-core","marks":["kl"]},{"_type":"span","_key":"kn","text":" (a widely used accessibility testing engine), and structural changes get a manual keyboard pass from the address bar through every control. Automated tools like these only cover part of WCAG; the rest is judgment, whether the alt text is actually useful, whether the reading order makes sense, so I treat the tooling as a safety net under the hands-on work, not a stand-in for it.","marks":[]}]},{"_type":"block","_key":"kq","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"kp","text":"Where it stops short","marks":[]}]},{"_type":"block","_key":"ks","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kr","text":"I aim for AA, not the stricter AAA, on purpose, in line with the W3C''s own guidance that AAA is not meant as a blanket requirement for a whole site. A couple of AAA rules pull against a brand-led design: the china-marker red used for the italic accents sits at about 5.6:1 and the grey caption text at about 6.2:1, both over the AA bar of 4.5:1 and under the 7:1 enhanced bar, for one. The main reading text, the headings and the links are well over 7:1. So the work targets AA and stops there by choice, not by oversight.","marks":[]}]},{"_type":"block","_key":"ku","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kt","text":"That is a line about polish, not about whether the site works. If a specific thing is genuinely hard for you to use, that is a bug, and the next section is how to flag it.","marks":[]}]},{"_type":"block","_key":"kw","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"kv","text":"Found a problem?","marks":[]}]},{"_type":"block","_key":"k11","style":"normal","markDefs":[{"_key":"ky","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"kx","text":"If a page is hard to read, hard to get through, or breaks with the assistive technology you rely on, email ","marks":[]},{"_type":"span","_key":"kz","text":"nathan@nixoncreativestudio.com","marks":["ky"]},{"_type":"span","_key":"k10","text":" and tell me what happened and what you were using. It reaches a real person, me, and I treat accessibility problems as real problems to fix, not as nice-to-haves.","marks":[]}]}]', 1, '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "summary", "intro", "rows", "show_toc") VALUES ('01M40ZH06JKEH23VJK03FP2SMZ', 'colophon', 'published', '2026-10-03T13:33:45.554Z', '2026-10-03T13:33:46.841Z', '2026-10-03T13:33:46.841Z', 2, 'en', '01M40ZH06JKEH23VJK03FP2SMZ', 'Colophon', 'Colophon', 'How this site is built: the tools, the type, and the accessibility and privacy standards behind it.', '[{"_type":"block","_key":"k1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"How this site is made, and the standards behind it. Custom-built, so the same care that goes into client work goes into my own.","marks":[]}]}]', '[{"label":"Built with","detail":"Custom-coded in Astro with TypeScript, styled with Tailwind CSS, and deployed to Cloudflare. The words and photographs are kept in a small content system (EmDash) that I edit from a browser. No page builder, no stock template, no lock-in."},{"label":"Typography","detail":"Headings are set in Bebas Neue, the face of the studio logo, and the reading text in Newsreader, with the system sans for buttons and labels. Both web fonts are self-hosted, so nothing loads from a third party."},{"label":"Accessibility","detail":"Built toward WCAG AA and checked automatically on every deploy. In plain terms: it works with a keyboard and with a screen reader, and the text stays readable on every background. There is a fuller statement on the accessibility page."},{"label":"Performance","detail":"Pages are put together on the Cloudflare network and then kept in a cache close to each visitor, images are resized to fit the screen, and the fonts ship with the site, so it stays fast on a phone and a slow connection."},{"label":"Look and motion","detail":"One light theme, with no dark mode and no theme switch. No WebGL or 3D effects: the only movement is a slow drift of light across a few backgrounds and small fade-ins as you scroll. All of it switches off if your device is set to reduce motion."},{"label":"Photography","detail":"There is no stock photography here. The pictures are real ones: client sites, and the portraits and snapshots on the About page."},{"label":"Privacy","detail":"Privacy-friendly analytics, no advertising trackers, and nothing following you from page to page."}]', 0);
INSERT OR REPLACE INTO ec_pages ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "title", "heading", "eyebrow", "summary", "intro", "content", "show_toc", "last_updated") VALUES ('01M40ZGR7P7VC4H1Z9Y6GFA34T', 'privacy', 'published', '2026-10-03T13:33:37.398Z', '2026-10-03T13:33:38.649Z', '2026-10-03T13:33:38.649Z', 2, 'en', '01M40ZGR7P7VC4H1Z9Y6GFA34T', 'Privacy', 'What this site collects.', 'Privacy notice', 'What this site collects, and what it does with it.', '[{"_type":"block","_key":"k4","style":"normal","markDefs":[{"_key":"k1","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k0","text":"Short version: a contact form, two analytics tools (a cookieless Cloudflare beacon and Google Analytics), and the things any web server logs. No advertising trackers. If you have questions, email ","marks":[]},{"_type":"span","_key":"k2","text":"nathan@nixoncreativestudio.com","marks":["k1"]},{"_type":"span","_key":"k3","text":".","marks":[]}]}]', '[{"_type":"block","_key":"k1","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k0","text":"Contact form","marks":[]}]},{"_type":"block","_key":"k6","style":"normal","markDefs":[{"_key":"k3","_type":"link","href":"https://web3forms.com/"}],"children":[{"_type":"span","_key":"k2","text":"When you submit the form on the Contact page, the fields you fill in (your name, email, organization type, budget range, and project description) are sent through ","marks":[]},{"_type":"span","_key":"k4","text":"Web3Forms","marks":["k3"]},{"_type":"span","_key":"k5","text":" and delivered to my inbox. Web3Forms acts as the delivery pipe and does not retain submissions beyond the brief window needed to deliver them. I keep the email in my inbox the same way I''d keep any project inquiry.","marks":[]}]},{"_type":"block","_key":"k8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k7","text":"The form also includes a hidden \"honeypot\" field that real visitors never fill in. If a bot submits the form and trips the honeypot, the message is quietly discarded.","marks":[]}]},{"_type":"block","_key":"ka","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k9","text":"Analytics","marks":[]}]},{"_type":"block","_key":"kc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kb","text":"The site uses two analytics tools, and I use both for the same thing: to see which pages are useful and which aren''t.","marks":[]}]},{"_type":"block","_key":"kg","style":"normal","markDefs":[{"_key":"kd","_type":"link","href":"https://www.cloudflare.com/web-analytics/"}],"children":[{"_type":"span","_key":"ke","text":"Cloudflare Web Analytics","marks":["kd"]},{"_type":"span","_key":"kf","text":" counts page views and basic performance metrics without cookies, without fingerprinting, and without sending data to any third-party advertising network.","marks":[]}]},{"_type":"block","_key":"kn","style":"normal","markDefs":[{"_key":"kh","_type":"link","href":"https://support.google.com/analytics/answer/6004245"},{"_key":"kk","_type":"link","href":"https://tools.google.com/dlpage/gaoptout"}],"children":[{"_type":"span","_key":"ki","text":"Google Analytics 4","marks":["kh"]},{"_type":"span","_key":"kj","text":" records page views, scrolls, and outbound clicks, and sends them to Google. It sets first-party cookies to tell returning visits apart, and it truncates IP addresses before storing anything. I do not use it for advertising, I have not linked it to any ad account, and I have not turned on Google Signals or any demographic reporting. To opt out everywhere, install Google''s ","marks":[]},{"_type":"span","_key":"kl","text":"browser add-on","marks":["kk"]},{"_type":"span","_key":"km","text":"; most tracker-blocking extensions and browsers also stop it.","marks":[]}]},{"_type":"block","_key":"kp","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ko","text":"Server logs","marks":[]}]},{"_type":"block","_key":"kr","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"kq","text":"The hosting platform (Cloudflare Workers) records standard request data: IP address, user agent, requested URL, response code, timestamp. These logs are retained for a short window and used for operational purposes like blocking abuse and diagnosing errors. They are not used to build profiles of visitors. Cloudflare also serves a small bot-detection script from the same network (its \"JavaScript Detections\"); it is part of the hosting platform, not something I added, and I do not use it to track anyone.","marks":[]}]},{"_type":"block","_key":"kt","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ks","text":"Cookies","marks":[]}]},{"_type":"block","_key":"kx","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"ku","text":"Google Analytics sets a small number of first-party cookies (the ","marks":[]},{"_type":"span","_key":"kv","text":"_ga","marks":["code"]},{"_type":"span","_key":"kw","text":" family) so it can tell a returning visit from a new one. They carry a random identifier, not your name or email, and the Analytics section above links the opt-out. Nothing else on the site sets cookies, and no page embeds a map, video or other third-party widget. If a future change adds more third-party content, this page will say so first.","marks":[]}]},{"_type":"block","_key":"kz","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"ky","text":"Your data","marks":[]}]},{"_type":"block","_key":"k14","style":"normal","markDefs":[{"_key":"k11","_type":"link","href":"mailto:nathan@nixoncreativestudio.com"}],"children":[{"_type":"span","_key":"k10","text":"If you''ve sent a project inquiry and want me to delete it from my inbox, email ","marks":[]},{"_type":"span","_key":"k12","text":"nathan@nixoncreativestudio.com","marks":["k11"]},{"_type":"span","_key":"k13","text":" with the email address you used to send it. I''ll confirm when it''s deleted.","marks":[]}]},{"_type":"block","_key":"k16","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k15","text":"Changes","marks":[]}]},{"_type":"block","_key":"k18","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k17","text":"If what the site collects changes, I''ll update this page and bump the date at the bottom. There''s no separate notification list for privacy updates.","marks":[]}]}]', 1, '2026-10-04T00:00:00.000Z');
